/**
 * Represents a registered guest (customer) of SmartStay Hotel.
 *
 * OOP concepts demonstrated:
 *   - Inheritance   : extends K2703399_Person, inheriting name, contact, email.
 *   - Polymorphism  : overrides getDetails() — when the method is called on an
 *                     K2703399_Person reference holding a K2703399_Guest object,
 *                     the guest's version executes (runtime polymorphism).
 *   - Encapsulation : guestId and nicPassport are private with getters only.
 *
 * Assumption: guestId is auto-generated by K2703399_HotelSystem at registration.
 *
 * @author  K.H. Nandun Lakshan De Silva
 * @id      K2703399
 * @module  CI6115 Programming III
 */
public class K2703399_Guest extends K2703399_Person {

    // -----------------------------------------------------------------------
    // Private fields
    // -----------------------------------------------------------------------
    private String guestId;      // system-generated unique ID (e.g. G0001)
    private String nicPassport;  // NIC or passport number — used as unique key

    // -----------------------------------------------------------------------
    // Constructor
    // -----------------------------------------------------------------------

    /**
     * Creates a fully-initialised Guest.
     * Calls the parent constructor via super() to set shared Person fields.
     *
     * @param guestId       system-generated guest identifier
     * @param nicPassport   NIC or passport number (stored in upper case)
     * @param fullName      guest's full name
     * @param contactNumber contact phone number
     * @param email         email address
     */
    public K2703399_Guest(String guestId, String nicPassport,
                         String fullName, String contactNumber, String email) {
        super(fullName, contactNumber, email); // invoke parent constructor (Inheritance)
        this.guestId     = guestId;
        this.nicPassport = nicPassport.toUpperCase(); // "n1234567" = "N1234567"
    }

    // -----------------------------------------------------------------------
    // Overridden method (Polymorphism)
    // -----------------------------------------------------------------------

    /**
     * Returns a formatted string with all guest details.
     * Overrides the abstract method declared in K2703399_Person.
     *
     * @return formatted guest details
     */
    @Override
    public String getDetails() {
        return String.format(
            "Guest ID: %-6s | Name: %-25s | NIC/Passport: %-15s | Contact: %-12s | Email: %s",
            guestId, fullName, nicPassport, contactNumber, email // inherited protected fields
        );
    }

    // -----------------------------------------------------------------------
    // Getters and Setters (Encapsulation)
    // -----------------------------------------------------------------------

    public String getGuestId()                     { return guestId; }

    // No setter: the NIC/passport is the guest's unique key in K2703399_HotelSystem,
    // so changing it would break the HashMap lookup.
    public String getNicPassport()                 { return nicPassport; }
}
